WITH metrics AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY units, id) AS seq_no, FIRST_VALUE(revenue, TRUE) OVER w_running AS first_known_revenue, ROW_NUMBER() OVER w_part AS row_seq FROM store_sales WHERE YEAR(sale_date) >= 2024 WINDOW w_running AS (PARTITION BY store_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (ORDER BY units DESC, id)) SELECT DATE_TRUNC('MONTH', sale_date) AS activity_month, PERCENTILE_APPROX(row_seq, 0.9) AS row_seq_p90, BIT_AND(units) AS units_bit_and, ROUND(AVG(units), 2) AS avg_units FROM metrics GROUP BY DATE_TRUNC('MONTH', sale_date) HAVING row_seq_p90 > 0;
